remote = {
    "url": "https://github.com/user/repo.git",
    "branches": ["master", "develop"],
    "objects": 42,
}

def clone(remote):
    print(f"Cloning into 'repo'...")
    print(f"remote: Enumerating objects: {remote['objects']}, done.")
    default_branch, other_branches = remote["branches"][0], remote["branches"][1:]
    remotes = {"origin": remote["url"]}
    return default_branch, other_branches, remotes

default_branch, other_branches, remotes = clone(remote)
print("Local branches:")
print(f"* {default_branch}")
print("remotes/origin/HEAD -> origin/master")
for name in other_branches:
    print(f"remotes/origin/{name}")
for name, url in remotes.items():
    print(f"{name}  {url} (fetch)")
    print(f"{name}  {url} (push)")
